use async_bb8_diesel::{
    AsyncConnection, AsyncRunQueryDsl, AsyncSaveChangesDsl, ConnectionError, OptionalExtension,
    PoolError,
};
use diesel::{pg::PgConnection, prelude::*};

table! {
    users (id) {
        id -> Integer,
        name -> Text,
    }
}

#[derive(AsChangeset, Insertable, Queryable, PartialEq, Eq, Clone)]
#[diesel(table_name = users)]
pub struct User {
    pub id: i32,
    pub name: String,
}

#[derive(AsChangeset, Identifiable)]
#[diesel(table_name = users)]
pub struct UserUpdate<'a> {
    pub id: i32,
    pub name: &'a str,
}

// Demonstrates an error which may be returned from transactions.
#[derive(thiserror::Error, Debug)]
enum MyError {
    #[error("DB error")]
    Db(#[from] PoolError),

    #[error("Custom transaction error")]
    Other,
}

impl From<diesel::result::Error> for MyError {
    fn from(error: diesel::result::Error) -> Self {
        MyError::Db(PoolError::Connection(ConnectionError::Query(error)))
    }
}

#[tokio::main]
async fn main() {
    use users::dsl;

    let manager = async_bb8_diesel::ConnectionManager::<PgConnection>::new("localhost:1234");
    let pool = bb8::Pool::builder().build(manager).await.unwrap();

    // Insert by values
    let _ = diesel::insert_into(dsl::users)
        .values((dsl::id.eq(0), dsl::name.eq("Jim")))
        .execute_async(&pool)
        .await
        .unwrap();

    // Insert by structure
    let _ = diesel::insert_into(dsl::users)
        .values(User {
            id: 0,
            name: "Jim".to_string(),
        })
        .execute_async(&pool)
        .await
        .unwrap();

    // Load
    let _ = dsl::users.get_result_async::<User>(&pool).await.unwrap();

    // Update
    let _ = diesel::update(dsl::users)
        .filter(dsl::id.eq(0))
        .set(dsl::name.eq("Jim, But Different"))
        .execute_async(&pool)
        .await
        .unwrap();

    // Update via save_changes
    let update = &UserUpdate { id: 0, name: "Jim" };
    let _ = update.save_changes_async::<User>(&pool).await.unwrap();

    // Delete
    let _ = diesel::delete(dsl::users)
        .filter(dsl::id.eq(0))
        .execute_async(&pool)
        .await
        .unwrap();

    // Transaction with multiple operations
    pool.transaction(|conn| {
        diesel::insert_into(dsl::users)
            .values((dsl::id.eq(0), dsl::name.eq("Jim")))
            .execute(conn)
            .unwrap();
        diesel::insert_into(dsl::users)
            .values((dsl::id.eq(1), dsl::name.eq("Another Jim")))
            .execute(conn)
            .unwrap();
        Ok::<(), PoolError>(())
    })
    .await
    .unwrap();

    // Transaction returning custom error types.
    let _: MyError = pool
        .transaction(|_| Err::<(), MyError>(MyError::Other {}))
        .await
        .unwrap_err();

    // Asynchronous transaction.
    pool.transaction_async(|conn| async move {
        diesel::update(dsl::users)
            .filter(dsl::id.eq(0))
            .set(dsl::name.eq("Let's change the name again"))
            .execute_async(&conn)
            .await
            .map_err(PoolError::Connection)
    })
    .await
    .unwrap();

    // Access the result via OptionalExtension
    assert!(dsl::users
        .filter(dsl::id.eq(12345))
        .first_async::<User>(&pool)
        .await
        .optional()
        .unwrap()
        .is_none());
}

//! An async-safe connection pool for Diesel.

use crate::{Connection, ConnectionError, PoolError, PoolResult};
use async_trait::async_trait;
use diesel::r2d2::{self, ManageConnection, R2D2Connection};
use std::sync::{Arc, Mutex, MutexGuard};
use tokio::task;

/// A connection manager which implements [`bb8::ManageConnection`] to
/// integrate with bb8.
///
/// ```no_run
/// use async_bb8_diesel::AsyncRunQueryDsl;
/// use diesel::prelude::*;
/// use diesel::pg::PgConnection;
///
/// table! {
///     users (id) {
///         id -> Integer,
///     }
/// }
///
/// #[tokio::main]
/// async fn main() {
///     use users::dsl;
///
///     // Creates a Diesel-specific connection manager for bb8.
///     let mgr = async_bb8_diesel::ConnectionManager::<PgConnection>::new("localhost:1234");
///     let pool = bb8::Pool::builder().build(mgr).await.unwrap();
///
///     // You can acquire connections to the pool manually...
///     diesel::insert_into(dsl::users)
///         .values(dsl::id.eq(1337))
///         .execute_async(&*pool.get().await.unwrap())
///         .await
///         .unwrap();
///
///     // ... Or just issue them to the pool directly.
///     diesel::insert_into(dsl::users)
///         .values(dsl::id.eq(1337))
///         .execute_async(&pool)
///         .await
///         .unwrap();
/// }
/// ```
#[derive(Clone)]
pub struct ConnectionManager<T> {
    inner: Arc<Mutex<r2d2::ConnectionManager<T>>>,
}

impl<T: Send + 'static> ConnectionManager<T> {
    pub fn new<S: Into<String>>(database_url: S) -> Self {
        Self {
            inner: Arc::new(Mutex::new(r2d2::ConnectionManager::new(database_url))),
        }
    }

    async fn run_blocking<R, F>(&self, f: F) -> R
    where
        R: Send + 'static,
        F: Send + 'static + FnOnce(&r2d2::ConnectionManager<T>) -> R,
    {
        let cloned = self.inner.clone();
        tokio::task::spawn_blocking(move || f(&*cloned.lock().unwrap()))
            .await
            // Intentionally panic if the inner closure panics.
            .unwrap()
    }
}

#[async_trait]
impl<T> bb8::ManageConnection for ConnectionManager<T>
where
    T: R2D2Connection + Send + 'static,
{
    type Connection = Connection<T>;
    type Error = ConnectionError;

    async fn connect(&self) -> Result<Self::Connection, Self::Error> {
        self.run_blocking(|m| m.connect())
            .await
            .map(Connection::new)
            .map_err(ConnectionError::Checkout)
    }

    async fn is_valid(&self, conn: &mut Self::Connection) -> Result<(), Self::Error> {
        let c = Connection(conn.0.clone());
        self.run_blocking(move |m| {
            m.is_valid(&mut c.inner())?;
            Ok(())
        })
        .await
    }

    fn has_broken(&self, _: &mut Self::Connection) -> bool {
        // Diesel returns this value internally. We have no way of calling the
        // inner method without blocking as this method is not async, but `bb8`
        // indicates that this method is not mandatory.
        false
    }
}

#[async_trait]
impl<Conn> crate::AsyncSimpleConnection<Conn, PoolError> for bb8::Pool<ConnectionManager<Conn>>
where
    Conn: 'static + R2D2Connection,
{
    #[inline]
    async fn batch_execute_async(&self, query: &str) -> PoolResult<()> {
        let self_ = self.clone();
        let query = query.to_string();
        let conn = self_.get_owned().await.map_err(PoolError::from)?;
        task::spawn_blocking(move || conn.inner().batch_execute(&query))
            .await
            .unwrap() // Propagate panics
            .map_err(PoolError::from)
    }
}

#[async_trait]
impl<Conn> crate::AsyncConnection<Conn, PoolError> for bb8::Pool<ConnectionManager<Conn>>
where
    Conn: 'static + R2D2Connection,
    bb8::Pool<ConnectionManager<Conn>>: crate::AsyncSimpleConnection<Conn, PoolError>,
{
    type OwnedConnection = bb8::PooledConnection<'static, ConnectionManager<Conn>>;

    async fn get_owned_connection(&self) -> Result<Self::OwnedConnection, PoolError> {
        let self_ = self.clone();
        Ok(self_.get_owned().await.map_err(PoolError::from)?)
    }

    fn as_sync_conn(owned: &Self::OwnedConnection) -> MutexGuard<'_, Conn> {
        owned.inner()
    }

    fn as_async_conn(owned: &Self::OwnedConnection) -> &crate::connection::Connection<Conn> {
        owned
    }
}

//! Async versions of traits for issuing Diesel queries.

use crate::connection::Connection as SingleConnection;
use async_trait::async_trait;
use diesel::{
    connection::{Connection as DieselConnection, SimpleConnection, TransactionManager},
    dsl::Limit,
    query_dsl::{
        methods::{ExecuteDsl, LimitDsl, LoadQuery},
        RunQueryDsl,
    },
    result::Error as DieselError,
};
use std::future::Future;
use std::sync::Arc;
use std::sync::MutexGuard;
use tokio::task::spawn_blocking;

/// An async variant of [`diesel::connection::SimpleConnection`].
#[async_trait]
pub trait AsyncSimpleConnection<Conn, ConnErr>
where
    Conn: 'static + SimpleConnection,
{
    async fn batch_execute_async(&self, query: &str) -> Result<(), ConnErr>;
}

/// An async variant of [`diesel::connection::Connection`].
#[async_trait]
pub trait AsyncConnection<Conn, ConnErr>: AsyncSimpleConnection<Conn, ConnErr>
where
    Conn: 'static + DieselConnection,
    ConnErr: From<DieselError> + Send + 'static,
    Self: Send,
{
    type OwnedConnection: Sync + Send + 'static;

    #[doc(hidden)]
    async fn get_owned_connection(&self) -> Result<Self::OwnedConnection, ConnErr>;
    #[doc(hidden)]
    fn as_sync_conn(owned: &Self::OwnedConnection) -> MutexGuard<'_, Conn>;
    #[doc(hidden)]
    fn as_async_conn(owned: &Self::OwnedConnection) -> &SingleConnection<Conn>;

    /// Runs the function `f` in an context where blocking is safe.
    ///
    /// Any error may be propagated through `f`, as long as that
    /// error type may be constructed from `ConnErr` (as that error
    /// type may also be generated).
    async fn run<R, E, Func>(&self, f: Func) -> Result<R, E>
    where
        R: Send + 'static,
        E: From<ConnErr> + Send + 'static,
        Func: FnOnce(&mut Conn) -> Result<R, E> + Send + 'static,
    {
        let connection = self.get_owned_connection().await?;
        Self::run_with_connection(connection, f).await
    }

    #[doc(hidden)]
    async fn run_with_connection<R, E, Func>(
        connection: Self::OwnedConnection,
        f: Func,
    ) -> Result<R, E>
    where
        R: Send + 'static,
        E: From<ConnErr> + Send + 'static,
        Func: FnOnce(&mut Conn) -> Result<R, E> + Send + 'static,
    {
        spawn_blocking(move || f(&mut *Self::as_sync_conn(&connection)))
            .await
            .unwrap() // Propagate panics
    }

    #[doc(hidden)]
    async fn run_with_shared_connection<R, E, Func>(
        connection: Arc<Self::OwnedConnection>,
        f: Func,
    ) -> Result<R, E>
    where
        R: Send + 'static,
        E: From<ConnErr> + Send + 'static,
        Func: FnOnce(&mut Conn) -> Result<R, E> + Send + 'static,
    {
        spawn_blocking(move || f(&mut *Self::as_sync_conn(&connection)))
            .await
            .unwrap() // Propagate panics
    }

    async fn transaction<R, E, Func>(&self, f: Func) -> Result<R, E>
    where
        R: Send + 'static,
        E: From<DieselError> + From<ConnErr> + Send + 'static,
        Func: FnOnce(&mut Conn) -> Result<R, E> + Send + 'static,
    {
        self.run(|conn| conn.transaction(|c| f(c))).await
    }

    async fn transaction_async<R, E, Func, Fut, 'a>(&'a self, f: Func) -> Result<R, E>
    where
        R: Send + 'static,
        E: From<DieselError> + From<ConnErr> + Send,
        Fut: Future<Output = Result<R, E>> + Send,
        Func: FnOnce(SingleConnection<Conn>) -> Fut + Send,
    {
        // Check out a connection once, and use it for the duration of the
        // operation.
        let conn = Arc::new(self.get_owned_connection().await?);

        // This function mimics the implementation of:
        // https://docs.diesel.rs/master/diesel/connection/trait.TransactionManager.html#method.transaction
        //
        // However, it modifies all callsites to instead issue
        // known-to-be-synchronous operations from an asynchronous context.
        Self::run_with_shared_connection(conn.clone(), |conn| {
            Conn::TransactionManager::begin_transaction(conn).map_err(ConnErr::from)
        })
        .await?;

        // TODO: The ideal interface would pass the "async_conn" object to the
        // underlying function "f" by reference.
        //
        // This would prevent the user-supplied closure + future from using the
        // connection *beyond* the duration of the transaction, which would be
        // bad.
        //
        // However, I'm struggling to get these lifetimes to work properly. If
        // you can figure out a way to convince that the reference lives long
        // enough to be referenceable by a Future, but short enough that we can
        // guarantee it doesn't live persist after this function returns, feel
        // free to make that change.
        let async_conn = SingleConnection(Self::as_async_conn(&conn).0.clone());
        match f(async_conn).await {
            Ok(value) => {
                Self::run_with_shared_connection(conn.clone(), |conn| {
                    Conn::TransactionManager::commit_transaction(conn).map_err(ConnErr::from)
                })
                .await?;
                Ok(value)
            }
            Err(user_error) => {
                match Self::run_with_shared_connection(conn.clone(), |conn| {
                    Conn::TransactionManager::rollback_transaction(conn).map_err(ConnErr::from)
                })
                .await
                {
                    Ok(()) => Err(user_error),
                    Err(err) => Err(err.into()),
                }
            }
        }
    }
}

/// An async variant of [`diesel::query_dsl::RunQueryDsl`].
#[async_trait]
pub trait AsyncRunQueryDsl<Conn, AsyncConn, E>
where
    Conn: 'static + DieselConnection,
{
    async fn execute_async(self, asc: &AsyncConn) -> Result<usize, E>
    where
        Self: ExecuteDsl<Conn>;

    async fn load_async<U>(self, asc: &AsyncConn) -> Result<Vec<U>, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>;

    async fn get_result_async<U>(self, asc: &AsyncConn) -> Result<U, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>;

    async fn get_results_async<U>(self, asc: &AsyncConn) -> Result<Vec<U>, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>;

    async fn first_async<U>(self, asc: &AsyncConn) -> Result<U, E>
    where
        U: Send + 'static,
        Self: LimitDsl,
        Limit<Self>: LoadQuery<'static, Conn, U>;
}

#[async_trait]
impl<T, AsyncConn, Conn, E> AsyncRunQueryDsl<Conn, AsyncConn, E> for T
where
    T: 'static + Send + RunQueryDsl<Conn>,
    Conn: 'static + DieselConnection,
    AsyncConn: Send + Sync + AsyncConnection<Conn, E>,
    E: From<DieselError> + Send + 'static,
{
    async fn execute_async(self, asc: &AsyncConn) -> Result<usize, E>
    where
        Self: ExecuteDsl<Conn>,
    {
        asc.run(|conn| self.execute(conn).map_err(E::from)).await
    }

    async fn load_async<U>(self, asc: &AsyncConn) -> Result<Vec<U>, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>,
    {
        asc.run(|conn| self.load(conn).map_err(E::from)).await
    }

    async fn get_result_async<U>(self, asc: &AsyncConn) -> Result<U, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>,
    {
        asc.run(|conn| self.get_result(conn).map_err(E::from)).await
    }

    async fn get_results_async<U>(self, asc: &AsyncConn) -> Result<Vec<U>, E>
    where
        U: Send + 'static,
        Self: LoadQuery<'static, Conn, U>,
    {
        asc.run(|conn| self.get_results(conn).map_err(E::from))
            .await
    }

    async fn first_async<U>(self, asc: &AsyncConn) -> Result<U, E>
    where
        U: Send + 'static,
        Self: LimitDsl,
        Limit<Self>: LoadQuery<'static, Conn, U>,
    {
        asc.run(|conn| self.first(conn).map_err(E::from)).await
    }
}

#[async_trait]
pub trait AsyncSaveChangesDsl<Conn, AsyncConn, E>
where
    Conn: 'static + DieselConnection,
{
    async fn save_changes_async<Output>(self, asc: &AsyncConn) -> Result<Output, E>
    where
        Self: Sized,
        Conn: diesel::query_dsl::UpdateAndFetchResults<Self, Output>,
        Output: Send + 'static;
}

#[async_trait]
impl<T, AsyncConn, Conn, E> AsyncSaveChangesDsl<Conn, AsyncConn, E> for T
where
    T: 'static + Send + Sync + diesel::SaveChangesDsl<Conn>,
    Conn: 'static + DieselConnection,
    AsyncConn: Send + Sync + AsyncConnection<Conn, E>,
    E: 'static + Send + From<DieselError>,
{
    async fn save_changes_async<Output>(self, asc: &AsyncConn) -> Result<Output, E>
    where
        Conn: diesel::query_dsl::UpdateAndFetchResults<Self, Output>,
        Output: Send + 'static,
    {
        asc.run(|conn| self.save_changes(conn).map_err(E::from))
            .await
    }
}

//! An example showing how to cutomize connections while using pooling.

use async_bb8_diesel::{AsyncSimpleConnection, Connection, ConnectionError};
use async_trait::async_trait;
use diesel::pg::PgConnection;

#[derive(Debug)]
struct ConnectionCustomizer {}

type DieselPgConn = Connection<PgConnection>;

#[async_trait]
impl bb8::CustomizeConnection<DieselPgConn, ConnectionError> for ConnectionCustomizer {
    async fn on_acquire(&self, connection: &mut DieselPgConn) -> Result<(), ConnectionError> {
        connection
            .batch_execute_async("please execute some raw sql for me")
            .await
    }
}

#[tokio::main]
async fn main() {
    let manager = async_bb8_diesel::ConnectionManager::<PgConnection>::new("localhost:1234");
    let _ = bb8::Pool::builder()
        .connection_customizer(Box::new(ConnectionCustomizer {}))
        .build(manager)
        .await
        .unwrap();
}

//! bb8-diesel allows the bb8 asynchronous connection pool
//! to be used underneath Diesel.
//!
//! This is currently implemented against Diesel's synchronous
//! API, with calls to [`tokio::task::spawn_blocking`] to safely
//! perform synchronous operations from an asynchronous task.

mod async_traits;
mod connection;
mod connection_manager;
mod error;

pub use async_traits::{
    AsyncConnection, AsyncRunQueryDsl, AsyncSaveChangesDsl, AsyncSimpleConnection,
};
pub use connection::Connection;
pub use connection_manager::ConnectionManager;
pub use error::{ConnectionError, ConnectionResult, OptionalExtension, PoolError, PoolResult};

//! An async wrapper around a [`diesel::Connection`].

use crate::{ConnectionError, ConnectionResult};
use async_trait::async_trait;
use diesel::r2d2::R2D2Connection;
use std::sync::{Arc, Mutex, MutexGuard};
use tokio::task;

/// An async-safe analogue of any connection that implements
/// [`diesel::Connection`].
///
/// These connections are created by [`crate::ConnectionManager`].
///
/// All blocking methods within this type delegate to
/// [`tokio::task::spawn_blocking`], meaning they won't block
/// any asynchronous work or threads.
pub struct Connection<C>(pub(crate) Arc<Mutex<C>>);

impl<C> Connection<C> {
    pub fn new(c: C) -> Self {
        Self(Arc::new(Mutex::new(c)))
    }

    // Accesses the underlying connection.
    //
    // As this is a blocking mutex, it's recommended to avoid invoking
    // this function from an asynchronous context.
    pub(crate) fn inner(&self) -> MutexGuard<'_, C> {
        self.0.lock().unwrap()
    }
}

#[async_trait]
impl<Conn> crate::AsyncSimpleConnection<Conn, ConnectionError> for Connection<Conn>
where
    Conn: 'static + R2D2Connection,
{
    #[inline]
    async fn batch_execute_async(&self, query: &str) -> ConnectionResult<()> {
        let diesel_conn = Connection(self.0.clone());
        let query = query.to_string();
        task::spawn_blocking(move || diesel_conn.inner().batch_execute(&query))
            .await
            .unwrap() // Propagate panics
            .map_err(ConnectionError::from)
    }
}

#[async_trait]
impl<Conn> crate::AsyncConnection<Conn, ConnectionError> for Connection<Conn>
where
    Conn: 'static + R2D2Connection,
    Connection<Conn>: crate::AsyncSimpleConnection<Conn, ConnectionError>,
{
    type OwnedConnection = Connection<Conn>;

    async fn get_owned_connection(&self) -> Result<Self::OwnedConnection, ConnectionError> {
        Ok(Connection(self.0.clone()))
    }

    fn as_sync_conn(owned: &Self::OwnedConnection) -> MutexGuard<'_, Conn> {
        owned.inner()
    }

    fn as_async_conn(owned: &Self::OwnedConnection) -> &Connection<Conn> {
        owned
    }
}

//! bb8-diesel allows the bb8 asynchronous connection pool
//! to be used underneath Diesel.
//!
//! This is currently implemented against Diesel's synchronous
//! API, with calls to [`tokio::task::spawn_blocking`] to safely
//! perform synchronous operations from an asynchronous task.

use diesel::result::Error as DieselError;
use diesel::OptionalExtension as OtherOptionalExtension;
use thiserror::Error;

/// Syntactic sugar around a Result returning an [`ConnectionError`].
pub type ConnectionResult<R> = Result<R, ConnectionError>;

/// Errors returned directly from Connection.
#[derive(Error, Debug)]
pub enum ConnectionError {
    #[error("Failed to checkout a connection: {0}")]
    Checkout(#[from] diesel::r2d2::Error),

    #[error("Failed to issue a query: {0}")]
    Query(#[from] DieselError),
}

/// Syntactic sugar around a Result returning an [`PoolError`].
pub type PoolResult<R> = Result<R, PoolError>;

/// Async variant of [diesel::prelude::OptionalExtension].
pub trait OptionalExtension<T> {
    fn optional(self) -> Result<Option<T>, PoolError>;
}

impl<T> OptionalExtension<T> for PoolResult<T> {
    fn optional(self) -> Result<Option<T>, PoolError> {
        let self_as_query_result: diesel::QueryResult<T> = match self {
            Ok(value) => Ok(value),
            Err(PoolError::Connection(ConnectionError::Query(error_kind))) => Err(error_kind),
            Err(e) => return Err(e),
        };

        self_as_query_result
            .optional()
            .map_err(|e| PoolError::Connection(ConnectionError::Query(e)))
    }
}

/// Describes an error performing an operation from a connection pool.
///
/// This is a superset of [`ConnectionError`] which also may
/// propagate errors attempting to access the connection pool.
#[derive(Error, Debug)]
pub enum PoolError {
    #[error("Failure accessing a connection: {0}")]
    Connection(#[from] ConnectionError),

    #[error("BB8 Timeout accessing connection")]
    Timeout,
}

impl From<DieselError> for PoolError {
    fn from(error: DieselError) -> Self {
        PoolError::Connection(ConnectionError::Query(error))
    }
}

impl From<bb8::RunError<ConnectionError>> for PoolError {
    fn from(error: bb8::RunError<ConnectionError>) -> Self {
        match error {
            bb8::RunError::User(e) => PoolError::Connection(e),
            bb8::RunError::TimedOut => PoolError::Timeout,
        }
    }
}
